<?php require_once __DIR__.'/_header.php';$keys=['R2_BUCKET','R2_ENDPOINT','R2_PUBLIC_BASE_URL'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($keys as $k){db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,trim($_POST[$k]??'')]);}$msg='Saved. R2 secrets remain in .env.';}function setting($k){$s=db()->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$s->execute([$k]);return $s->fetchColumn()?:env($k,'');}?><h1>Settings</h1><?php if($msg):?><p class="ok"><?=e($msg)?></p><?php endif;?><form method="post" class="card"><?=csrf_field()?><label>R2 Bucket<input name="R2_BUCKET" value="<?=e(setting('R2_BUCKET'))?>"></label><label>R2 Endpoint<input name="R2_ENDPOINT" value="<?=e(setting('R2_ENDPOINT'))?>"></label><label>R2 Public Base URL<input name="R2_PUBLIC_BASE_URL" value="<?=e(setting('R2_PUBLIC_BASE_URL'))?>"></label><button>Save</button></form><p>R2 access key and secret must be configured in <code>.env</code>.</p><?php require __DIR__.'/_footer.php';